import Foundation

extension DigitalGuides {
    static let onlineSafety = DirectoryGuide(
        cardSummary: .init(ukrainian: "Фальшиві сайти, викрадені доступи та дії після шахрайства", german: "Falsche Websites, gestohlene Zugänge und Hilfe nach Betrug"),
        introduction: .init(ukrainian: "Шахраї копіюють банки, пошту, FinanzOnline та ID Austria. Дійте залежно від того, що саме було розкрито: посилання, пароль, код чи гроші.", german: "Betrüger kopieren Banken, Post, FinanzOnline und ID Austria. Die nächsten Schritte hängen davon ab, ob Link, Passwort, Code oder Geld betroffen sind."),
        sections: [
            .init("recognize", "link", "Перевірте повідомлення до відкриття", "Nachricht vor dem Öffnen prüfen", "Не переходьте за неочікуваним посиланням у SMS, листі, месенджері чи QR-коді, особливо якщо вимагають терміново «оновити дані» або сплатити невелику суму. Ім’я відправника й логотип легко підробити. Самостійно відкрийте відомий сайт або офіційний застосунок і перевірте, чи там справді є повідомлення або борг.", "Unerwarteten Links aus SMS, E-Mail, Messenger oder QR-Code nicht folgen, besonders bei dringender „Datenaktualisierung“ oder kleiner Zahlungsforderung. Absendername und Logo lassen sich fälschen. Bekannte Website selbst eingeben oder offizielle App öffnen und dort Nachricht oder Forderung prüfen.", source: phishing),
            .init("accounts", "lock.shield", "Захистіть важливі доступи", "Wichtige Zugänge absichern", "Використовуйте різні довгі паролі для пошти, банку й державних сервісів; увімкніть доступний другий фактор і блокування телефона. Не передавайте коди підтвердження телефоном, у чаті чи через віддалений доступ. Запит у застосунку ID Austria підтверджуйте лише тоді, коли ви самі щойно почали відповідний вхід або підпис.", "Für E-Mail, Bank und Behörden verschiedene lange Passwörter nutzen, verfügbaren zweiten Faktor und Gerätesperre aktivieren. Bestätigungscodes weder am Telefon noch im Chat oder per Fernzugriff weitergeben. Eine Anfrage in der ID-Austria-App nur bestätigen, wenn Sie die entsprechende Anmeldung oder Signatur selbst eben begonnen haben.", source: phishing),
            .init("credentials", "key.fill", "Якщо ввели пароль або код", "Wenn Passwort oder Code eingegeben wurde", "Закрийте підроблений сайт і відкрийте справжній сервіс самостійно з іншого безпечного пристрою. Негайно змініть пароль постраждалого облікового запису, а якщо він повторювався — і в інших сервісах; перевірте активні сеанси й контактні дані. Для ID Austria або пошти зверніться до офіційної підтримки, якщо втратили доступ чи бачите чужі дії.", "Gefälschte Seite schließen und den echten Dienst selbst auf einem sicheren Gerät öffnen. Passwort des betroffenen Kontos sofort ändern, bei Wiederverwendung auch anderswo; aktive Sitzungen und Kontaktdaten prüfen. Bei ID Austria oder E-Mail den offiziellen Support kontaktieren, wenn Zugriff fehlt oder fremde Aktionen sichtbar sind.", source: phishing),
            .init("payment", "creditcard", "Якщо ввели платіжні дані", "Wenn Zahlungsdaten eingegeben wurden", "Відразу зателефонуйте банку за номером з картки або офіційного сайту, заблокуйте картку чи онлайн-банкінг і повідомте про невідомі операції. Збережіть SMS, URL сторінки, скріншоти, час і суми; не переказуйте «додатковий платіж для повернення коштів». Банк пояснить подальше оскарження конкретного платежу.", "Sofort die Bank über die Nummer auf der Karte oder ihrer offiziellen Website anrufen, Karte oder Online-Banking sperren und unbekannte Umsätze melden. SMS, URL, Screenshots, Uhrzeit und Beträge sichern; keine „zusätzliche Zahlung zur Rückerstattung“ leisten. Die Bank erklärt die Reklamation der konkreten Zahlung.", source: phishing),
            .init("malware", "laptopcomputer", "Якщо надали віддалений доступ", "Wenn Fernzugriff gewährt wurde", "Якщо за вказівкою «підтримки» встановили програму віддаленого доступу, від’єднайте пристрій від інтернету й не вводьте на ньому нові паролі. З іншого пристрою повідомте банк і змініть критичні доступи. Зверніться до фахівця для перевірки пристрою перед повторним використанням; збережіть назву програми та листування як докази.", "Wurde auf Anweisung einer angeblichen „Supportstelle“ Fernwartungssoftware installiert, Gerät vom Internet trennen und dort keine neuen Passwörter eingeben. Von anderem Gerät Bank informieren und wichtige Zugänge ändern. Gerät vor erneuter Nutzung fachkundig prüfen lassen; Programmname und Nachrichten als Belege sichern.", source: phishing),
            .init("report", "checkmark.shield", "Повідомте й подайте заяву", "Melden und Anzeige erstatten", "За підозри повідомте Cybercrime-Meldestelle Bundeskriminalamt: against-cybercrime@bmi.gv.at. Це лише повідомлення, не заява про злочин. Якщо завдано шкоди чи викрадено дані, зверніться до найближчої поліційної дільниці із збереженими повідомленнями, URL, номерами та підтвердженнями платежів. Не видаляйте докази до консультації.", "Verdacht der Cybercrime-Meldestelle des Bundeskriminalamts unter against-cybercrime@bmi.gv.at melden. Das ist ein Hinweis, keine Strafanzeige. Bei Schaden oder gestohlenen Daten mit gesicherten Nachrichten, URLs, Nummern und Zahlungsbelegen zur nächsten Polizeiinspektion gehen. Belege bis zur Klärung nicht löschen.", source: police)
        ], sources: [phishing, police]
    )
}
